code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO2 2
#define GPIO3 3
#define INTERVAL_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO3);
    if (!line3) {
        perror("gpiod_chip_get_line(GPIO3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line2, "gpio2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO2)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line3, "gpio3", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs (low).\n");
    fflush(stdout);

    /* Main loop: toggle every 2 seconds until signal */
    while (keep_running) {
        /* GPIO 2 HIGH, GPIO 3 LOW */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO2 HIGH)");
            break;
        }
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO3 LOW)");
            break;
        }
        printf("GPIO 2 HIGH, GPIO 3 LOW\n");
        fflush(stdout);
        sleep(INTERVAL_SEC);

        if (!keep_running) break;

        /* GPIO 2 LOW, GPIO 3 HIGH */
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO2 LOW)");
            break;
        }
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO3 HIGH)");
            break;
        }
        printf("GPIO 2 LOW, GPIO 3 HIGH\n");
        fflush(stdout);
        sleep(INTERVAL_SEC);
    }

cleanup:
    /* Ensure lines are low on exit */
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_set_value(line3, 0);
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (keep_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO2 2
#define GPIO3 3
#define DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO2);
    if (!line2) {
        perror("gpiod_chip_get_line GPIO2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO3);
    if (!line3) {
        perror("gpiod_chip_get_line GPIO3");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "gpio2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output GPIO2");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line3, "gpio3", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output GPIO3");
        goto cleanup;
    }

    while (keep_running) {
        gpiod_line_set_value(line2, 1);
        gpiod_line_set_value(line3, 0);
        printf("GPIO2 HIGH, GPIO3 LOW\n");
        fflush(stdout);
        usleep(DELAY_MS * 1000);

        gpiod_line_set_value(line2, 0);
        gpiod_line_set_value(line3, 1);
        printf("GPIO2 LOW, GPIO3 HIGH\n");
        fflush(stdout);
        usleep(DELAY_MS * 1000);
    }

    printf("\nExiting cleanly...\n");

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define STATE_CHANGE_INTERVAL 5
#define MAX_VALID_STATES 2

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio2-state", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        for (int i = 0; i < MAX_VALID_STATES && program_running; i++) {
            int value = i;
            if (gpiod_line_set_value(line, value) < 0) {
                fprintf(stderr, "Failed to set GPIO %d to %d: %s\n", GPIO_LINE_OFFSET, value, strerror(errno));
                goto cleanup;
            }
            printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);
            fflush(stdout);
            sleep(1);
        }
        if (program_running) {
            sleep(STATE_CHANGE_INTERVAL);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Program terminated.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 3.3
#define SAMPLE_INTERVAL 0.5

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main() {
    int fd;
    int16_t raw;
    int16_t config;
    uint8_t reg;
    uint8_t buf[2];
    int16_t config_val;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
    config = 0x4000; // MUX: AIN0 single-ended (1000), PGA: +/-4.096V (0000)
    config |= 0x0200; // MODE: continuous conversion (10)
    config |= 0x0100; // DR: 128 SPS (01)
    config |= 0x0003; // COMP: disable comparator

    // Write config register
    reg = CONFIG_REG;
    buf[0] = reg;
    buf[1] = config;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write config register");
        close(fd);
        return 1;
    }

    // Wait for first conversion (128 SPS -> ~7.8ms, use 10ms for safety)
    usleep(10000);

    while (keep_running) {
        // Write pointer to conversion register
        reg = CONVERSION_REG;
        buf[0] = reg;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to set conversion register pointer");
            break;
        }

        // Read 2 bytes
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read conversion data");
            break;
        }

        raw = (int16_t)((buf[0] << 8) | buf[1]);
        // Convert to voltage: raw * 4.096 / 32768
        float voltage = (raw * 4.096f) / 32768.0f;
        printf("Voltage: %.4f V\n", voltage);

        // Wait for next sample
        usleep((useconds_t)(SAMPLE_INTERVAL * 1000000));
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5a
#define I2C_BUS "/dev/i2c-1"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_write_byte: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mlx90614(int fd, float *temperature) {
    uint8_t reg = 0x00;
    if (i2c_write_byte(fd, reg) < 0) {
        return -1;
    }

    uint8_t data[2];
    if (i2c_read_bytes(fd, data, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temperature = (float)raw * 0.02f - 273.15f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90614 initialized at 0x%02X on %s\n", MLX90614_ADDR, I2C_BUS);

    while (g_running) {
        float temperature;
        if (read_mlx90614(fd, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature from MLX90614.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

