#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define REG_CONVERSION 0x00
#define REG_CONFIG 0x01

#define CONFIG_OS_SINGLE 0x8000
#define CONFIG_MUX_AIN0_GND 0x4000
#define CONFIG_PGA_4_096V 0x0200
#define CONFIG_MODE_SINGLE 0x0100
#define CONFIG_DR_128SPS 0x0080

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write16: write");
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read16: write reg");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read16: read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS;
        if (i2c_write16(fd, REG_CONFIG, config) < 0) {
            fprintf(stderr, "Failed to write config\n");
            break;
        }

        uint16_t conv;
        if (i2c_read16(fd, REG_CONVERSION, &conv) < 0) {
            fprintf(stderr, "Failed to read conversion\n");
            break;
        }

        int16_t raw = (int16_t)conv;
        printf("AIN0: %d\n", raw);
        fflush(stdout);

        usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

