#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is pigpiod running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("PWM on GPIO %d running at %d Hz, range %d. Press Ctrl+C to stop.\n",
           PWM_PIN, PWM_FREQ, PWM_RANGE);
    fflush(stdout);

    while (running) {
        if (gpioPWM(PWM_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM high on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("PWM HIGH\n");
        fflush(stdout);
        time_sleep(0.5);

        if (!running) break;

        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM low on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("PWM LOW\n");
        fflush(stdout);
        time_sleep(0.5);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define TRIG_PULSE_US 10
#define LOOP_INTERVAL_S 60
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1;
    long elapsed_ns;
    double distance_cm;

    /* Ensure trigger is low for at least 2 us */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIG high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(TRIG_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed_ns = (t1.tv_sec - t0.tv_sec) * 1000000000L + (t1.tv_nsec - t0.tv_nsec);
        if (elapsed_ns > 1000000000L) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);

    /* Wait for echo falling edge */
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed_ns = (t1.tv_sec - t0.tv_sec) * 1000000000L + (t1.tv_nsec - t0.tv_nsec);
        if (elapsed_ns > 1000000000L) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t1);
    elapsed_ns = (t1.tv_sec - t0.tv_sec) * 1000000000L + (t1.tv_nsec - t0.tv_nsec);

    distance_cm = (double)elapsed_ns / 58.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance_cm;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        fprintf(stderr, "Error: failed to get TRIG line %d: %s\n", TRIG_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get ECHO line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Error: failed to request TRIG as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: failed to request ECHO as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        double distance = measure_distance(trig, echo);

        if (distance < 0.0) {
            fprintf(stderr, "Error: measurement failed, continuing...\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < LOOP_INTERVAL_S && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x28
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define ADC_MAX 32767.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000; /* AIN0 single-ended, PGA 4.096V, 128 SPS, continuous */
    if (i2c_write_reg(fd, CONFIG_REG, config) < 0) {
        fprintf(stderr, "ADS1115 init failed: config write failed\n");
        return -1;
    }
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t config;
    if (i2c_read_reg(fd, CONFIG_REG, &config) < 0) return -1;
    if (!(config & 0x8000)) {
        fprintf(stderr, "ADS1115 conversion not ready\n");
        return -1;
    }
    if (i2c_read_reg(fd, CONVERSION_REG, &config) < 0) return -1;
    *raw = (int16_t)config;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "ADS1115 init failed; device may be absent or unresponsive\n");
        close(fd);
        return 1;
    }

    while (running) {
        int16_t raw;
        if (ads1115_read(fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        double voltage = (raw * REF_VOLTAGE) / ADC_MAX;
        printf("Raw: %d, Voltage: %.3f V\n", raw, voltage);
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

#include <stdio.h>
