        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_ads1115(int fd, int16_t *raw) {
    uint16_t config = 0x8000 | 0x4000 | 0x0000 | 0x0000 | 0x0000 | 0x0000 | 0x0000;
    if (i2c_write_reg(fd, CONFIG_REG, config) < 0) return -1;
    usleep(10000);
