#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define ADC_RESOLUTION 32768.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_ads1115(int fd, int16_t *raw) {
    uint16_t config = 0x8000 | 0x4000 | 0x0000 | 0x0000 | 0x0000 | 0x0000;
    if (i2c_write_reg(fd, CONFIG_REG, config) < 0) return -1;
    usleep(10000);
    uint16_t val;
    if (i2c_read_reg(fd, CONVERSION_REG, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    int16_t raw;
    for (int i = 0; i < 3 && running; i++) {
        if (read_ads1115(fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed at iteration %d\n", i + 1);
            close(fd);
            return 1;
        }
        double voltage = (raw * REF_VOLTAGE) / ADC_RESOLUTION;
        printf("Raw: %d, Voltage: %.3f V\n", raw, voltage);
        sleep(1);
    }

    close(fd);
    return 0;
}

