#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO2 2
#define GPIO3 3
#define GPIO5 5
#define NUM_GPIOS 3

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_GPIOS];
    int pins[NUM_GPIOS] = {GPIO2, GPIO3, GPIO5};
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio2-gpio3-gpio5", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("GPIO 2, 3, 5 initialized as outputs. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_GPIOS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high: %s\n", pins[i], strerror(errno));
            }
        }
        sleep(1);
        for (int i = 0; i < NUM_GPIOS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low: %s\n", pins[i], strerror(errno));
            }
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

