#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 400.0

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {0, (long)us * 1000L};
    nanosleep(&ts, NULL);
}

static void trigger_sensor(struct gpiod_line *trig) {
    gpiod_line_set_value(trig, 1);
    sleep_us(10);
    gpiod_line_set_value(trig, 0);
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1;
    long long start, end;
    int timeout = 0;

    trigger_sensor(trig);

    while (gpiod_line_get_value(echo) == 0) {
        if (++timeout > 100000) {
            fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
            return -1.0;
        }
        sleep_us(1);
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);
    start = (long long)t0.tv_sec * 1000000LL + t0.tv_nsec / 1000LL;

    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++timeout > 100000) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
            return -1.0;
        }
        sleep_us(1);
    }

    clock_gettime(CLOCK_MONOTONIC, &t1);
    end = (long long)t1.tv_sec * 1000000LL + t1.tv_nsec / 1000LL;

    double elapsed = (double)(end - start) / 1000000.0;
    double distance = (elapsed * SPEED_OF_SOUND) / 2.0;

    if (distance < 0.0 || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance %.2f out of range.\n", distance);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (keep_running) {
        double distance = measure_distance(trig, echo);
        if (distance >= 0.0) {
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        }
        sleep(1);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

