#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_2 2
#define GPIO_PIN_3 3
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int set_output_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_3, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "gpio3", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_3, strerror(errno));
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs.\n");
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        if (set_output_value(line2, 1) < 0) {
            goto cleanup;
        }
        if (set_output_value(line3, 1) < 0) {
            goto cleanup;
        }
        printf("GPIO 2 and GPIO 3 set to HIGH.\n");
        sleep(POLL_INTERVAL_SEC);

        if (!program_running) {
            break;
        }

        if (set_output_value(line2, 0) < 0) {
            goto cleanup;
        }
        if (set_output_value(line3, 0) < 0) {
            goto cleanup;
        }
        printf("GPIO 2 and GPIO 3 set to LOW.\n");
        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

