#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27
#define NUM_PINS 5

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int pins[NUM_PINS] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_27};
    int i;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip 0 (default for Raspberry Pi)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request each line as output, initially low
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio4_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Starting GPIO control loop. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high\n", pins[i]);
            }
        }
        printf("GPIOs HIGH\n");
        usleep(50000);

        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", pins[i]);
            }
        }
        printf("GPIOs LOW\n");
        usleep(50000);
    }

    printf("\nExiting cleanly.\n");

cleanup:
    // Release lines and close chip
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

