    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-test", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %u high\n", pins[i]);
                goto cleanup;
            }
        }
        usleep(50000);
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %u low\n", pins[i]);
                goto cleanup;
            }
        }
        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

