#include <signal.h>
#include <gpiod.h>

#define GPIO_4 4
#define GPIO_17 17
#define CONSUMER "gpio4-17"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret;

    /* Install signal handlers for clean exit */
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get line 4 */
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line (GPIO 4)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get line 17 */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO 17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line 4 as output, initial value 0 */
    ret = gpiod_line_request_output(line4, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }

    /* Request line 17 as output, initial value 0 */
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    printf("GPIO 4 and GPIO 17 initialized as outputs (0).\n");

    /* Main loop: toggle every 0.01 seconds */
    while (keep_running) {
        gpiod_line_set_value(line4, 1);
        gpiod_line_set_value(line17, 1);
        usleep(10000); /* 10 ms */

        gpiod_line_set_value(line4, 0);
        gpiod_line_set_value(line17, 0);
        usleep(10000); /* 10 ms */
    }

    printf("\nExiting cleanly.\n");

cleanup:
    /* Release lines and close chip */
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

