#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_2 2
#define GPIO_PIN_3 3
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN_3, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio2_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "gpio3_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN_3, strerror(errno));
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_PIN_2, strerror(errno));
            goto cleanup;
        }
        printf("GPIO 2 HIGH\n");
        usleep(POLL_INTERVAL_US);

        if (!program_running) break;

        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_PIN_2, strerror(errno));
            goto cleanup;
        }
        printf("GPIO 2 LOW\n");
        usleep(POLL_INTERVAL_US);

        if (!program_running) break;

        if (gpiod_line_set_value(line3, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_PIN_3, strerror(errno));
            goto cleanup;
        }
        printf("GPIO 3 HIGH\n");
        usleep(POLL_INTERVAL_US);

        if (!program_running) break;

        if (gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_PIN_3, strerror(errno));
            goto cleanup;
        }
        printf("GPIO 3 LOW\n");
        usleep(POLL_INTERVAL_US);
