#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pin);
    }
}

static void apply_state(int state) {
    set_pwm(PWM_PIN_1, state);
    set_pwm(PWM_PIN_2, state);
    set_pwm(PWM_PIN_3, state);
    printf("State: %s\n", state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        apply_state(1);
        sleep(LOOP_DELAY);
        if (!running) break;
        apply_state(0);
        sleep(LOOP_DELAY);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define READ_INTERVAL 60

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "i2c write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_htu21d(int fd, float *temperature) {
    uint8_t cmd = 0x2E;
    uint8_t data[3];

    if (i2c_write(fd, &cmd, 1) < 0)
        return -1;

    usleep(20000);

    if (i2c_read(fd, data, 3) < 0)
        return -1;

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    raw &= 0xFFFC;

    float t = -46.85f + 175.72f * (raw / 65536.0f);

    if (t < -40.0f || t > 125.0f) {
        fprintf(stderr, "HTU21D out-of-range reading: %.2f C\n", t);
        return -1;
    }

    *temperature = t;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HTU21D_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HTU21D at 0x%02X on %s. Reading every %d seconds. Ctrl-C to exit.\n",
           HTU21D_ADDR, I2C_DEV, READ_INTERVAL);

    while (g_running) {
        float temp;
        if (read_htu21d(fd, &temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

