#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FILTER_CTL 0x2F
#define ADXL345_REG_DEVID 0x00

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg: read");
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg(fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0xE5)\n", devid);
        return -1;
    }

    if (i2c_write_reg(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_reg(fd, ADXL345_REG_FILTER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (adxl345_init(fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("ADXL345 initialized at 0x%02X\n", ADXL345_ADDRESS);

    while (running) {
        uint8_t x = 0;
        if (i2c_read_reg(fd, ADXL345_REG_DATAX0, &x) < 0) {
            fprintf(stderr, "Failed to read X axis\n");
            break;
        }
        int16_t raw = (int16_t)((x << 8) | ((uint8_t)(x >> 8)));
        printf("X: %d\n", raw);
        usleep(100000);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define CYCLES 50
#define DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initially low */
    if (gpiod_line_request_output(line, "gpio27", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting 50 cycles on GPIO %d. Press Ctrl+C to exit early.\n", GPIO_LINE);

    for (int i = 0; i < CYCLES && keep_running; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (high)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d HIGH\n", i + 1, GPIO_LINE);
        usleep(DELAY_MS * 1000);

        if (!keep_running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value (low)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d LOW\n", i + 1, GPIO_LINE);
        usleep(DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

