#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, int pin) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;
    int last_state = 1;
    int counter = 0;
    int bit_idx = 0;

    for (i = 0; i < 40; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == last_state) {
            counter++;
            usleep(1);
            if (counter > 255) return -1;
        }
        last_state = gpiod_line_get_value(line);

        if (counter > 16) {
            data[bit_idx / 8] <<= 1;
            if (counter > 10) data[bit_idx / 8] |= 1;
            bit_idx++;
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;
    return (data[0] << 8) | data[1];
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {DHT22_PIN_1, DHT22_PIN_2, DHT22_PIN_3, DHT22_PIN_4};
    int ret = 0;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            ret = 1;
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "dht22") < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input\n", pins[i]);
            ret = 1;
            goto cleanup;
        }
    }

    while (running) {
        int d1 = read_dht22(lines[0], DHT22_PIN_1);
        int d2 = read_dht22(lines[1], DHT22_PIN_2);
        int d3 = read_dht22(lines[2], DHT22_PIN_3);
        int d4 = read_dht22(lines[3], DHT22_PIN_4);

        if (d1 == 40 && d2 == 40 && d3 == 40 && d4 == 40) {
            printf("All DHT22 sensors read successfully.\n");
        } else {
            printf("Error reading DHT22 sensors.\n");
        }
        fflush(stdout);
        sleep(2);
    }

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define STEP_DELAY 0.5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void report_state(int s1, int s2, int s3) {
    printf("State: S1=%d S2=%d S3=%d\n", s1, s2, s3);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (set_pwm(PWM_PIN_1, 128) != 0 ||
            set_pwm(PWM_PIN_2, 128) != 0 ||
            set_pwm(PWM_PIN_3, 128) != 0) {
            break;
        }
        report_state(128, 128, 128);
        time_sleep(STEP_DELAY);
        if (!running) break;

        if (set_pwm(PWM_PIN_1, 0) != 0 ||
            set_pwm(PWM_PIN_2, 0) != 0 ||
            set_pwm(PWM_PIN_3, 0) != 0) {
            break;
        }
        report_state(0, 0, 0);
        time_sleep(STEP_DELAY);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

