        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO2, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO3);
    if (!line3) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO3, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO3, strerror(errno));
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs (0).\n");
    fflush(stdout);

    while (keep_running) {
        gpiod_line_set_value(line2, 1);
        gpiod_line_set_value(line3, 1);
        sleep(1);
        gpiod_line_set_value(line2, 0);
        gpiod_line_set_value(line3, 0);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 22
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio22-control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output control started. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (keep_running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE);
        usleep(POLL_INTERVAL_US);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE);
        usleep(POLL_INTERVAL_US);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is pigpiod running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: failed to set PWM frequency to %d Hz\n", PWM_FREQ);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    while (running) {
        if (gpioPWM(PWM_PIN, 50) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle\n");
            break;
        }
        printf("State: ON\n");
        fflush(stdout);
        time_sleep(0.02);
        if (!running) break;

        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to reset PWM duty cycle\n");
            break;
        }
        printf("State: OFF\n");
        fflush(stdout);
        time_sleep(0.02);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
