#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_byte(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    usleep(3000);
    if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x01) < 0) return -1;
    return 0;
}

static int tcs34725_read_color(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t r_raw, g_raw, b_raw, c_raw;
    if (i2c_read_byte(fd, TCS34725_CDATA, &c_raw) < 0) return -1;
    if (i2c_read_byte(fd, TCS34725_RDATA, &r_raw) < 0) return -1;
    if (i2c_read_byte(fd, TCS34725_GDATA, &g_raw) < 0) return -1;
    if (i2c_read_byte(fd, TCS34725_BDATA, &b_raw) < 0) return -1;
    *c = (uint16_t)c_raw;
    *r = (uint16_t)r_raw;
    *g = (uint16_t)g_raw;
    *b = (uint16_t)b_raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read_color(fd, &r, &g, &b, &c) == 0) {
            printf("R: %u, G: %u, B: %u, C: %u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Error reading color data.\n");
        }
        usleep(200000);
    }

    close(fd);
    return 0;
}

