#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_22 22
#define GPIO_27 27
#define DELAY_MS 10

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line22 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line22) {
        perror("gpiod_chip_get_line 22");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line 27");
        goto cleanup;
    }

    if (gpiod_line_request_output(line22, "gpio22", 0) < 0) {
