#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define SSD1306_I2C_ADDR 0x3D
#define I2C_DEVICE "/dev/i2c-1"

static int i2c_fd = -1;

void cleanup(int signum) {
    (void)signum;
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int ssd1306_init() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Initialize SSD1306
    unsigned char init_cmds[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
        0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12,
        0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6,
        0xAF
    };

    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (write(i2c_fd, &init_cmds[i], 1) != 1) {
            perror("Failed to write init command");
            close(i2c_fd);
            i2c_fd = -1;
            return -1;
        }
    }

    return 0;
}

int ssd1306_write_command(unsigned char cmd) {
    unsigned char buf[2] = {0x00, cmd};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write command");
        return -1;
    }
    return 0;
}

int ssd1306_write_data(unsigned char data) {
    unsigned char buf[2] = {0x40, data};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int ssd1306_display_text(int x, int y, const char *text) {
    unsigned char buf[17];
    buf[0] = 0x40;
    buf[1] = 0x00;
    buf[2] = 0x10;
    buf[3] = 0x00;
    buf[4] = 0x00;
    buf[5] = 0x00;
    buf[6] = 0x00;
    buf[7] = 0x00;
    buf[8] = 0x00;
    buf[9] = 0x00;
    buf[10] = 0x00;
    buf[11] = 0x00;
    buf[12] = 0x00;
    buf[13] = 0x00;
    buf[14] = 0x00;
    buf[15] = 0x00;
    buf[16] = (unsigned char)(text[x] & 0xFF);

    for (int i = 0; text[i] != '\0'; i++) {
        buf[16 + i] = (unsigned char)(text[i] & 0xFF);
    }

    if (write(i2c_fd, buf, 17) != 17) {
        perror("Failed to write text");
        return -1;
    }
    return 0;
}

