#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO2 2
#define GPIO3 3
#define GPIO5 5
#define INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO2);
    lines[1] = gpiod_chip_get_line(chip, GPIO3);
    lines[2] = gpiod_chip_get_line(chip, GPIO5);
    if (!lines[0] || !lines[1] || !lines[2]) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(lines[0], "gpio2", 0) < 0) {
        perror("gpiod_line_request_output GPIO2");
        goto cleanup;
    }
    if (gpiod_line_request_output(lines[1], "gpio3", 0) < 0) {
        perror("gpiod_line_request_output GPIO3");
        goto cleanup;
    }
    if (gpiod_line_request_output(lines[2], "gpio5", 0) < 0) {
        perror("gpiod_line_request_output GPIO5");
        goto cleanup;
    }

    printf("GPIO 2, 3, 5 initialized as outputs. Press Ctrl+C to exit.\n");

    while (keep_running) {
        gpiod_line_set_value(lines[0], 1);
        gpiod_line_set_value(lines[1], 1);
        gpiod_line_set_value(lines[2], 1);
        printf("GPIO 2, 3, 5 set HIGH\n");
        sleep(INTERVAL_SEC);

        if (!keep_running) break;

        gpiod_line_set_value(lines[0], 0);
        gpiod_line_set_value(lines[1], 0);
        gpiod_line_set_value(lines[2], 0);
        printf("GPIO 2, 3, 5 set LOW\n");
        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        printf("PWM ON\n");
        fflush(stdout);
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            gpioPWM(pins[i], 255);
        }
        gpioDelay(1000000);

        printf("PWM OFF\n");
        fflush(stdout);
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            gpioPWM(pins[i], 0);
        }
        gpioDelay(1000000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define ECHO_TIMEOUT_US 300000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int trigger_sensor(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 1) < 0) {
        perror("gpiod_line_set_value (high)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }
    return 0;
}

static long long measure_pulse(struct gpiod_line *echo) {
    long long start = now_us();
    if (start < 0) return -1;

    int val;
    long long elapsed = 0;
    while ((val = gpiod_line_get_value(echo)) == 0) {
        if (now_us() - start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
        elapsed = now_us() - start;
    }

    start = now_us();
    if (start < 0) return -1;

    while ((val = gpiod_line_get_value(echo)) == 1) {
        if (now_us() - start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
        elapsed = now_us() - start;
    }

    return elapsed;
}

static long long get_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    if (trigger_sensor(trigger) < 0) return -1;
    long long pulse = measure_pulse(echo);
    if (pulse < 0) return -1;
    return (pulse > 0) ? (pulse / 58) : -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        long long dist = get_distance(trigger, echo);
        if (dist >= 0) {
            printf("Distance: %lld cm\n", dist);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }
        usleep(200000);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
