#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write: write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "i2c_read: read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write(fd, 0x6B, 0x00) < 0) return -1;
    if (i2c_write(fd, 0x6A, 0x3B) < 0) return -1;
    return 0;
}

static int read_mpu6050(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read(fd, 0x3B, buf, 14) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 init failed (device absent or bus error)\n");
        close(fd);
        return 1;
    }

    int16_t ax, ay, az, gx, gy, gz;
    int rc = 0;

    for (int i = 0; i < 100 && running; i++) {
        if (read_mpu6050(fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "read_mpu6050 failed at iteration %d\n", i + 1);
            rc = 1;
            break;
        }
        printf("ax=%6d ay=%6d az=%6d gx=%6d gy=%6d gz=%6d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);
        usleep(10000);
    }

    close(fd);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_14 14
#define GPIO_15 15
#define CONSUMER "gpio14-15-control"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_14, strerror(errno));
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_15, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line14, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_14, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_15, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and GPIO %d initialized as outputs.\n", GPIO_14, GPIO_15);
    printf("Applying state to these lines every %d seconds. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_SEC);

    while (keep_running) {
        printf("Applying state to GPIO %d and GPIO %d...\n", GPIO_14, GPIO_15);

        if (gpiod_line_set_value(line14, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_14, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line15, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_15, strerror(errno));
            break;
        }

        printf("State applied.\n");
        sleep(POLL_INTERVAL_SEC);
        if (!keep_running)
            break;

        if (gpiod_line_set_value(line14, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_14, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line15, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_15, strerror(errno));
            break;
        }

        printf("State cleared.\n");
        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line14)
        gpiod_line_release(line14);
    if (line15)
        gpiod_line_release(line15);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

