#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 23
#define CONSUMER "gpio23"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM pin 23 */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line 23");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line 23 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 23 initialized as output. Press Ctrl+C to exit.\n");

    /* Main loop: toggle every 5 seconds */
    while (keep_running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO 23 high");
            break;
        }
        printf("GPIO 23 set HIGH\n");
        sleep(5);

        if (!keep_running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO 23 low");
            break;
        }
        printf("GPIO 23 set LOW\n");
        sleep(5);
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 22
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    int val;

    for (;;) {
        val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-val));
            return -1;
        }
        if (val == target) return 0;
        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
            perror("clock_gettime");
            return -1;
        }
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                          (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > timeout_us) return -1;
    }
}

static int measure(struct gpiod_line *trig, struct gpiod_line *echo) {
    int elapsed;
    int val;

    /* Ensure trigger is low for at least 2 us */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting TRIG low: %s\n", strerror(-gpiod_line_set_value(trig, 0)));
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error setting TRIG high: %s\n", strerror(-gpiod_line_set_value(trig, 1)));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting TRIG low: %s\n", strerror(-gpiod_line_set_value(trig, 0)));
        return -1;
    }

    /* Wait for echo rising edge */
    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1;
    }

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge */
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &now);
    elapsed = (now.tv_sec - start.tv_sec) * 1000000L +
              (now.tv_nsec - start.tv_nsec) / 1000L;

    if (elapsed < 0 || elapsed > 20000) {
        fprintf(stderr, "Invalid measurement: %d us\n", elapsed);
        return -1;
    }

    return elapsed;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int dist = measure(trig, echo);
        if (dist < 0) {
            fprintf(stderr, "Measurement failed; continuing.\n");
        } else {
            printf("Distance: %d mm\n", dist);
            fflush(stdout);
        }
        usleep(100000);
    }

    printf("\nExiting...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

