#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor1"
#define MQTT_CLIENT_ID "rpi_sensor1"
#define MQTT_KEEPALIVE 60
#define POLL_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int publish_mqtt(const char *topic, const char *payload) {
    int rc = mosquitto_publish(
        NULL,
        NULL,
        topic,
        (int)strlen(payload),
        payload,
        0,
        false
    );
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_publish failed: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    printf("MQTT publisher started. Press Ctrl+C to stop.\n");

    while (running) {
        if (publish_mqtt(MQTT_TOPIC, "Sensor reading: 42") != 0) {
            fprintf(stderr, "Failed to publish MQTT message\n");
        }
        sleep(POLL_INTERVAL);
    }

    gpioTerminate();
    printf("MQTT publisher stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 100
#define PWM_FREQ 1000
#define LOOP_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is pigpiod running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("PWM on GPIO %d started. Press Ctrl+C to stop.\n", PWM_PIN);
    fflush(stdout);

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Error: gpioPWM failed at level %d\n", i);
                running = 0;
                break;
            }
            printf("PWM level: %d\n", i);
            fflush(stdout);
            sleep(1);
        }
        if (running) {
            for (int i = PWM_RANGE; i >= 0 && running; i--) {
                if (gpioPWM(PWM_PIN, i) != 0) {
                    fprintf(stderr, "Error: gpioPWM failed at level %d\n", i);
                    running = 0;
                    break;
                }
                printf("PWM level: %d\n", i);
                fflush(stdout);
                sleep(1);
            }
        }
        if (running) {
            sleep(LOOP_INTERVAL);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define CONSUMER "hc-sr04"

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {0, (long)us * 1000L};
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line trig");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line echo");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        /* Ensure trigger is low for at least 2 us */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            goto cleanup;
        }
        sleep_us(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value trig high");
            goto cleanup;
        }
        sleep_us(10);

        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            goto cleanup;
        }

        /* Wait for echo rising edge */
        int val;
        int timeout = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value echo");
                goto cleanup;
            }
            if (val == 1) break;
            sleep_us(1);
            timeout++;
        } while (timeout < 100000);

        if (val != 1) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            goto cleanup;
        }

        /* Wait for echo falling edge */
        timeout = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value echo");
                goto cleanup;
            }
            if (val == 0) break;
            sleep_us(1);
            timeout++;
        } while (timeout < 100000);

        if (val != 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            goto cleanup;
        }

        unsigned int elapsed_us = timeout;
        float distance = (float)elapsed_us / 58.0f;

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

#define PWM_RANGE 1000
#define PWM_FREQ 1000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (int i = 0; i < 4; i++) {
        gpioSetMode(pins[i], PI_OUTPUT);
        gpioSetPWMrange(pins[i], PWM_RANGE);
        gpioSetPWMfrequency(pins[i], PWM_FREQ);
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        printf("PWM state: 1\n");
        fflush(stdout);
        gpioPWM(PWM_PIN_1, 1);
        gpioPWM(PWM_PIN_2, 1);
        gpioPWM(PWM_PIN_3, 1);
        gpioPWM(PWM_PIN_4, 1);
        time_sleep(0.1);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

