#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor1"
#define MQTT_CLIENT_ID "raspberrypi_sensor1"
#define NUM_READINGS 10
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG 0xC383

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115(int handle, int16_t *value) {
    char config[2];
    char reg[1] = {ADS1115_REG_CONFIG};
    char conv[2];
    int16_t raw;

    config[0] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE) >> 6;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE) << 8;

    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, config[0]) < 0) return -1;
    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, config[1]) < 0) return -1;

    gpioDelay(10000);

    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, ADS1115_REG_CONVERSION) < 0) return -1;
    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, ADS1115_REG_CONVERSION) < 0) return -1;

    gpioDelay(10000);

    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERSION, conv, 2) != 2) return -1;

    raw = (conv[0] << 8) | conv[1];
    *value = raw;
    return 0;
}

int main() {
    int handle;
    int rc;
    char payload[32];
    int i;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    while (running && i < NUM_READINGS) {
        int16_t raw;
        if (read_ads1115(handle, &raw) < 0) {
            fprintf(stderr, "Read failed\n");
            break;
        }

        snprintf(payload, sizeof(payload), "%d", raw);
        rc = mosquitto_publish(mosquitto_lib_init(), MQTT_BROKER, MQTT_TOPIC,
                               strlen(payload), payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "MQTT publish failed: %s\n", mosquitto_strerror(rc));
            break;
        }
        i++;
        gpioDelay(100000);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

