static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, int32_t *dig_T1, int32_t *dig_T2, int32_t *dig_T3,
                                   int32_t *dig_P1, int32_t *dig_P2, int32_t *dig_P3,
                                   int32_t *dig_P4, int32_t *dig_P5, int32_t *dig_P6,
                                   int32_t *dig_P7, int32_t *dig_P8, int32_t *dig_P9) {
    uint8_t cal[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, cal, sizeof(cal)) < 0) return -1;

    *dig_T1 = (cal[1] << 8) | cal[0];
    *dig_T2 = (cal[3] << 8) | cal[2];
    *dig_T3 = (cal[5] << 8) | cal[4];
    *dig_P1 = (cal[7] << 8) | cal[6];
    *dig_P2 = (cal[9] << 8) | cal[8];
    *dig_P3 = (cal[11] << 8) | cal[10];
    *dig_P4 = (cal[13] << 8) | cal[12];
    *dig_P5 = (cal[15] << 8) | cal[14];
    *dig_P6 = (cal[17] << 8) | cal[16];
    *dig_P7 = (cal[19] << 8) | cal[18];
    *dig_P8 = (cal[21] << 8) | cal[20];
    *dig_P9 = (cal[23] << 8) | cal[22];
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: cannot read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID 0x%02X does not match expected 0x%02X\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: cannot reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t ctrl;
    if (i2c_read_reg(fd, BMP280_REG_CTRL_MEAS, &ctrl, 1) < 0) {
        fprintf(stderr, "Error: cannot read ctrl_meas: %s\n", strerror(errno));
        return -1;
    }
    if ((ctrl & 0x09) != 0x00) {
        fprintf(stderr, "Error: ctrl_meas not clear (0x%02X)\n", ctrl);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: cannot write config: %s\n", strerror(errno));
        return -1;
    }

    if (bmp280_read_calibration(fd, &dig_T1, &dig_T2, &dig_T3,
                                &dig_P1, &dig_P2, &dig_P3,
                                &dig_P4, &dig_P5, &dig_P6,
                                &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "Error: cannot read calibration data: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: cannot write ctrl_meas: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, buf, 6) < 0) {
        fprintf(stderr, "Error: cannot read raw data: %s\n", strerror(errno));
        return -1;
    }
    *raw_p = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    *raw_t = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static int32_t bmp280_compensate_temp(int32_t raw_t, int32_t dig_T1, int32_t dig_T2, int32_t dig_T3) {
    int32_t var1, var2, T;
    var1 = ((((raw_t >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)dig_T1)) * ((raw_t >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    T = var1 + var2;
    return T;
}

static int32_t bmp280_compensate_press(int32_t raw_p, int32_t dig_P1, int32_t dig_P2, int32_t dig_P3,
                                        int32_t dig_P4, int32_t dig_P5, int32_t dig_P6,
                                        int32_t dig_P7, int32_t dig_P8, int32_t dig_P9, int32_t raw_t) {
    int64_t var1, var2, p;
    var1 = ((int64_t)raw_t) - 128000;
    var2 = var1 * var1 * (int64_t)dig_P1;
    var2 = var2 + ((var1 * (int64_t)dig_P2) << 17);
    var2 = var2 + (((int64_t)dig_P3) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P4) >> 15) + ((var1 * (int64_t)dig_P5) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P6) >> 26;
    var2 = (((int64_t)dig_P7) * ((int64_t)raw_t)) >> 14;
    var2 = var2 + (((int64_t)dig_P8) * ((int64_t)raw_t)) >> 50;
    var2 = var2 + (((int64_t)dig_P9) << 2);
    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P10) * p) >> 15;
    var2 = (((int64_t)dig_P11) * p) >> 39;
    p = (p + ((var1 + var2 + ((int64_t)dig_P12)) >> 8)) / 100;
    return (int32_t)p;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "Error: BMP280 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("BMP280 initialized at 0x%02X. Reading every 5 seconds. Press Ctrl+C to exit.\n", BMP280_I2C_ADDR);

    while (running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Warning: read failed, retrying in 5s\n");
            sleep(5);
            continue;
        }

        int32_t t = bmp280_compensate_temp(raw_t, dig_T1, dig_T2, dig_T3);
        int32_t p = bmp280_compensate_press(raw_p, dig_P1, dig_P2, dig_P3,
                                            dig_P4, dig_P5, dig_P6,
                                            dig_P7, dig_P8, dig_P9, t);

        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", t / 100.0, p / 100.0);
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("PWM on GPIO %d initialised. Press Ctrl+C to exit.\n", PWM_PIN);
    fflush(stdout);

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO5 5
#define GPIO6 6
#define GPIO13 13
#define CONSUMER "gpio5-6-13"

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO5, GPIO6, GPIO13};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed\n", pins[i]);
            goto cleanup;
        }
    }

    printf("GPIO %d, %d, %d set to LOW\n", GPIO5, GPIO6, GPIO13);
    fflush(stdout);

    while (running) {
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

