    if (gpioSetPWMrange(PWM_PIN_3, 100) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with all pins off */
    if (set_pwm(PWM_PIN_1, 0) != 0 ||
        set_pwm(PWM_PIN_2, 0) != 0 ||
        set_pwm(PWM_PIN_3, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO %d, %d, %d at 100 Hz. Press Ctrl+C to stop.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
    fflush(stdout);

    while (running) {
