#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define DHT22_CHIP "/dev/gpiochip0"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_ms) {
    int elapsed = 0;
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (val == target) return 0;
        if (elapsed >= timeout_ms) return -1;
        usleep(1000);
        elapsed += 1;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int i;

    /* Start signal: pull low for >=1ms, then high for 30us */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        fprintf(stderr, "request_output failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "set_value high failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(30);
    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "request_input failed: %s\n", strerror(errno));
        return -1;
    }

    /* Switch to input; wait for sensor to pull low (response) */
    if (wait_for_level(line, 0, 1000) < 0) return -1;
    if (!keep_running) return -1;
    if (wait_for_level(line, 1, 1000) < 0) return -1;
    if (!keep_running) return -1;
    if (wait_for_level(line, 0, 1000) < 0) return -1;
    if (!keep_running) return -1;

    /* Read 40 bits */
    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, 1000) < 0) return -1;
        if (!keep_running) return -1;
        if (wait_for_level(line, 0, 1000) < 0) return -1;
        if (!keep_running) return -1;

        int high_us = 0;
        while (keep_running) {
            int val = gpiod_line_get_value(line);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
                return -1;
            }
            if (val == 0) break;
            high_us++;
            usleep(1);
        }
        if (!keep_running) return -1;

        data[i / 8] <<= 1;
        if (high_us > 50) {
            data[i / 8] |= 1;
        }
    }

    /* Checksum */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: %d != %d\n", checksum, data[4]);
        return -1;
    }

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name(DHT22_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (read_dht22(line, &temperature, &humidity) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 data.\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

