#define I2C_BUS 1
#define MCP3008_CHANNEL 0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor1"
#define MQTT_CLIENT_ID "mcp3008_sensor"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (i2cWriteDevice(handle, (char *)tx, 3) != 0) {
        fprintf(stderr, "i2cWriteDevice failed\n");
        return -1;
    }

    if (i2cReadDevice(handle, (char *)rx, 3) != 3) {
        fprintf(stderr, "i2cReadDevice failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void publish_mqtt(int handle, int sensor_value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    int rc = mosquitto_publish(handle, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_publish failed: %s\n", mosquitto_strerror(rc));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "mosquitto_lib_init failed: %s\n", mosquitto_strerror(rc));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_cleanup();

    while (running) {
        int sensor_value = read_mcp3008(i2c_handle, MCP3008_CHANNEL);
        if (sensor_value < 0) {
            fprintf(stderr, "Sensor read failed, exiting\n");
            break;
        }
        publish_mqtt(NULL, sensor_value);
        sleep(1);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

