#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x30
#define NUM_PINS 4

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("i2c_write_byte: write");
        return -1;
    }
    return 0;
}

static int display_init(int fd) {
    unsigned char init_seq[] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80};
    for (int i = 0; i < 8; i++) {
        if (i2c_write_byte(fd, init_seq[i]) < 0) return -1;
    }
    return 0;
}

static int display_set_value(int fd, int pin, int value) {
    unsigned char byte = 0;
    if (value) byte |= (1 << pin);
    if (i2c_write_byte(fd, byte) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (display_init(fd) < 0) {
        fprintf(stderr, "Failed to initialize PCF8574\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (display_set_value(fd, 0, 1) < 0) break;
        if (display_set_value(fd, 1, 1) < 0) break;
        if (display_set_value(fd, 2, 0) < 0) break;
        if (display_set_value(fd, 3, 1) < 0) break;
        usleep(500000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

