#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hc-sr04"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = { .tv_sec = us / 1000000U,
                           .tv_nsec = (long)(us % 1000000U) * 1000L };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        /* Ensure trigger is low for at least 2 us before pulse. */
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger, 0)");
            goto cleanup;
        }
        sleep_us(5);

        /* 10 us trigger pulse. */
        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value(trigger, 1)");
            goto cleanup;
        }
        sleep_us(10);

        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger, 0)");
            goto cleanup;
        }

        /* Wait for echo rising edge. */
        int val;
        int timeout = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) break;
            sleep_us(1);
            timeout++;
        } while (timeout < 100000);

        if (val != 1) {
            fprintf(stderr, "Timeout waiting for echo rising edge.\n");
            goto cleanup;
        }

        /* Measure echo high duration. */
        int echo_high = 0;
        timeout = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) break;
            if (timeout > 100000) {
                fprintf(stderr, "Timeout waiting for echo falling edge.\n");
                goto cleanup;
            }
            sleep_us(1);
            timeout++;
        } while (1);

        unsigned int elapsed_us = timeout;

        /* Speed of sound: 343 m/s => 0.0343 us/um. */
        unsigned int distance = (elapsed_us * 343U / 2U) / 1000000U;

        printf("Distance: %u mm\n", distance);
        fflush(stdout);

        sleep_us(1000000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

