#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24
#define PWM_RANGE 100
#define STEP_DELAY 0.1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Starting PWM on GPIO %d, %d, %d. Press Ctrl+C to stop.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);

    while (running) {
        if (set_pwm(PWM_PIN_1, 50) != 0) break;
        if (set_pwm(PWM_PIN_2, 75) != 0) break;
        if (set_pwm(PWM_PIN_3, 100) != 0) break;
        time_sleep(STEP_DELAY);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 400.0

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line trig");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line echo");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (keep_running) {
        /* Ensure trigger is low for at least 2 us */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            goto cleanup;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value trig high");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            goto cleanup;
        }

        /* Wait for echo rising edge */
        int waited = 0;
        while (gpiod_line_get_value(echo) == 0) {
            if (!keep_running) break;
            if (waited > 100000) {
                fprintf(stderr, "Timeout waiting for echo rising edge\n");
                goto cleanup;
            }
            usleep(1);
            waited++;
        }
        if (!keep_running) break;
        if (waited > 100000) {
            goto cleanup;
        }

        /* Measure echo high duration */
        int echo_count = 0;
        while (gpiod_line_get_value(echo) == 1) {
            if (!keep_running) break;
            if (echo_count > 100000) {
                fprintf(stderr, "Timeout waiting for echo falling edge\n");
                goto cleanup;
            }
            usleep(1);
            echo_count++;
        }
        if (!keep_running) break;
        if (echo_count > 100000) {
            goto cleanup;
        }

        long long echo_us = (long long)echo_count;
        double distance = (echo_us / 1000000.0) * SPEED_OF_SOUND / 2.0;

        if (distance < 0.0 || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            goto cleanup;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
