#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_4, 255) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting PWM on GPIO 17, 18, 22, 27. Press Ctrl+C to stop.\n");
    fflush(stdout);

    while (running) {
        if (set_pwm(PWM_PIN_1, 128) != 0 ||
            set_pwm(PWM_PIN_2, 128) != 0 ||
            set_pwm(PWM_PIN_3, 128) != 0 ||
            set_pwm(PWM_PIN_4, 128) != 0) {
            break;
        }
        gpioDelay(100000);
        if (set_pwm(PWM_PIN_1, 0) != 0 ||
            set_pwm(PWM_PIN_2, 0) != 0 ||
