#include <gpiod.h>

#define GPIO2 2
#define GPIO3 3
#define GPIO17 17
#define NUM_PINS 3
#define CYCLES 3

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS] = {NULL};
    int pins[NUM_PINS] = {GPIO2, GPIO3, GPIO17};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio2_control", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < CYCLES && running; i++) {
        printf("Cycle %d/%d\n", i + 1, CYCLES);
        for (int j = 0; j < NUM_PINS; j++) {
            if (gpiod_line_set_value(lines[j], 1) < 0) {
                fprintf(stderr, "Failed to set line %d high\n", pins[j]);
                goto cleanup;
            }
            usleep(100000);
            if (gpiod_line_set_value(lines[j], 0) < 0) {
                fprintf(stderr, "Failed to set line %d low\n", pins[j]);
                goto cleanup;
            }
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

