#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PIN 18
#define NUM_PIXELS 10
#define DELAY_US 5000

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    for (int cycle = 0; cycle < 3 && running; cycle++) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            gpioWrite(GPIO_PIN, (i % 2 == 0) ? 1 : 0);
        }
        gpioDelay(DELAY_US);
    }

    gpioTerminate();
    return 0;
}

