#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define W1_PATH "/sys/bus/w1/devices"
#define W1_DEVICE "/w1_slave"
#define GPIO_PIN 4
#define READINGS 3
#define SLEEP_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int read_temp(const char *path, float *out) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[256];
    char line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for %s\n", path);
        return -1;
    }

    char *t = strstr(line2, "t=");
    if (!t) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }

    long raw = strtol(t + 2, NULL, 10);
    *out = raw / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char device_path[256];
    snprintf(device_path, sizeof(device_path), "%s/%d/%d", W1_PATH, GPIO_PIN, GPIO_PIN);

    for (int i = 0; i < READINGS && keep_running; i++) {
        if (read_temp(device_path, &float temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(SLEEP_SEC);
    }

    return 0;
}

