#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int trigger_pulse(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 1) < 0) {
        perror("gpiod_line_set_value (high)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        return -1;
    }
    return 0;
}

static long long measure_pulse(struct gpiod_line *echo) {
    long long start = now_us();
    if (start < 0) return -1;

    int val;
    long long elapsed = 0;
    while ((val = gpiod_line_get_value(echo)) == 0) {
        if (val < 0) {
            perror("gpiod_line_get_value (low)");
            return -1;
        }
        if (now_us() - start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
        elapsed = now_us() - start;
    }

    start = now_us();
    if (start < 0) return -1;

    while ((val = gpiod_line_get_value(echo)) == 1) {
        if (val < 0) {
            perror("gpiod_line_get_value (high)");
            return -1;
        }
        if (now_us() - start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
        elapsed = now_us() - start;
    }

    return elapsed;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line (trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (trigger_pulse(trigger) < 0) {
            goto cleanup;
        }

        long long elapsed = measure_pulse(echo);
        if (elapsed < 0) {
            goto cleanup;
        }

        long long distance = (elapsed - 5) / 58;
        if (distance < 2 || distance > 400) {
            fprintf(stderr, "Out of range: %lld us\n", elapsed);
            goto cleanup;
        }

        printf("Distance: %lld mm\n", distance);
        fflush(stdout);

        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define NUM_CYCLES 10

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initially low */
    if (gpiod_line_request_output(line, "gpio17_control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting 10-cycle control of GPIO %d. Press Ctrl+C to exit early.\n", GPIO_PIN);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value HIGH");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d set HIGH\n", i + 1, GPIO_PIN);
        usleep(100000); /* 100 ms */

        if (!keep_running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d set LOW\n", i + 1, GPIO_PIN);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

