#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_RETRIES 5
#define MAX_READS 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* --- MCU start signal: pull low for >=1 ms, then high --- */
        if (gpiod_line_request_output(line, "dht22", 0) < 0) {
            fprintf(stderr, "request_output failed: %s\n", strerror(errno));
            return -1;
        }
        usleep(2000); /* 2 ms low */

        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "set_value high failed: %s\n", strerror(errno));
            return -1;
        }
        usleep(30);  /* 30 us high */

        /* --- Switch to input; DHT22 pulls low --- */
        if (gpiod_line_request_input(line, "dht22") < 0) {
            fprintf(stderr, "request_input failed: %s\n", strerror(errno));
            return -1;
        }

        /* --- Wait for DHT22 response: low ~80 us, high ~80 us --- */
        int waited = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (running == 0) return -1;
            usleep(1);
            waited++;
            if (waited > 100) return -1;
        }
        waited = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (running == 0) return -1;
            usleep(1);
            waited++;
            if (waited > 100) return -1;
        }
        waited = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (running == 0) return -1;
            usleep(1);
            waited++;
            if (waited > 100) return -1;
        }

        /* --- Read 40 bits --- */
        for (bit_idx = 0; bit_idx < 40; bit_idx++) {
            waited = 0;
            while (gpiod_line_get_value(line) == 0) {
                if (running == 0) return -1;
                usleep(1);
                waited++;
                if (waited > 100) return -1;
            }
            waited = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (running == 0) return -1;
                usleep(1);
                waited++;
                if (waited > 100) return -1;
            }

            data[byte_idx] <<= 1;
            if (bit_idx % 2 == 0) data[byte_idx] |= 1;

            if (bit_idx % 8 == 7) byte_idx++;
        }

        /* --- Checksum --- */
        int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
        if (checksum != data[4]) {
            fprintf(stderr, "Checksum error (attempt %d)\n", attempt + 1);
            return -1;
        }

        /* --- Convert --- */
        *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
        *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
        if (data[2] & 0x80) *temp = -*temp;

        return 0;
    }

    fprintf(stderr, "DHT22 read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < MAX_READS && running; i++) {
        float temp, hum;
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Failed to read DHT22 on cycle %d\n", i + 1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

