#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_PIN_4 27

#define NUM_PINS 4
#define CYCLES 5
#define DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pin);
    }
}

static void all_off(void) {
    set_pwm(PWM_PIN_1, 0);
    set_pwm(PWM_PIN_2, 0);
    set_pwm(PWM_PIN_3, 0);
    set_pwm(PWM_PIN_4, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int pins[NUM_PINS] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set mode on pin %d\n", pins[i]);
            all_off();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Warning: could not set frequency on pin %d\n", pins[i]);
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Warning: could not initialise PWM on pin %d\n", pins[i]);
            all_off();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        printf("Cycle %d/%d\n", cycle + 1, CYCLES);
        for (int i = 0; i < NUM_PINS; i++) {
            set_pwm(pins[i], 255);
        }
        sleep(DELAY_SEC);
        for (int i = 0; i < NUM_PINS; i++) {
            set_pwm(pins[i], 0);
        }
        sleep(DELAY_SEC);
    }

    all_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

