#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23
#define PWM_PIN_5 24
#define PWM_PIN_6 25

#define PWM_RANGE 1000
#define PWM_FREQ 1000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5, PWM_PIN_6};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMrange(pins[0], PWM_RANGE) != 0 ||
        gpioSetPWMrange(pins[1], PWM_RANGE) != 0 ||
        gpioSetPWMrange(pins[2], PWM_RANGE) != 0 ||
        gpioSetPWMrange(pins[3], PWM_RANGE) != 0 ||
        gpioSetPWMrange(pins[4], PWM_RANGE) != 0 ||
        gpioSetPWMrange(pins[5], PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(pins[0], PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(pins[1], PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(pins[2], PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(pins[3], PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(pins[4], PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(pins[5], PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        for (int i = 0; i <= PWM_RANGE && keep_running; i++) {
            for (size_t j = 0; j < sizeof(pins) / sizeof(pins[0]); j++) {
                if (gpioPWM(pins[j], i) != 0) {
                    fprintf(stderr, "Failed to set PWM on pin %d\n", pins[j]);
                    keep_running = 0;
                    break;
                }
            }
            printf("PWM range: %d\n", i);
            fflush(stdout);
            gpioDelay(5000);
        }
    }

    for (size_t j = 0; j < sizeof(pins) / sizeof(pins[0]); j++) {
        gpioPWM(pins[j], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

