#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define DHT22_MAX_RETRIES 5
#define DHT22_READ_INTERVAL_SEC 60
#define DHT22_CYCLES 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int attempt;

    for (attempt = 0; attempt < DHT22_MAX_RETRIES; attempt++) {
        /* --- MCU start signal: pull low for >=1 ms, then high --- */
        if (gpiod_line_request_output(line, "dht22", 0) < 0) {
            fprintf(stderr, "Failed to request output for pin %d: %s\n",
                    DHT22_PIN_1, strerror(errno));
            return -1;
        }
        usleep(2000);  /* 2 ms low */

        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set pin %d high: %s\n",
                    DHT22_PIN_1, strerror(errno));
            return -1;
        }
        usleep(30);    /* 30 us high */

        /* --- Switch to input --- */
        if (gpiod_line_request_input(line, "dht22") < 0) {
            fprintf(stderr, "Failed to request input for pin %d: %s\n",
                    DHT22_PIN_1, strerror(errno));
            return -1;
        }

        /* --- Sensor response: low ~80 us, high ~80 us --- */
        int timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            usleep(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 no response (low timeout)\n");
                return -1;
            }
        }
        timeout = 0;
        while (gpiod_line_get_value(line) == 0) {
            usleep(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 no response (high timeout)\n");
                return -1;
            }
        }
        timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            usleep(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 no response (end timeout)\n");
                return -1;
            }
        }

        /* --- Read 40 bits --- */
        for (bit_idx = 0; bit_idx < 40; bit_idx++) {
            timeout = 0;
            while (gpiod_line_get_value(line) == 0) {
                usleep(1);
                timeout++;
                if (timeout > 100) {
                    fprintf(stderr, "DHT22 timeout on bit %d (low)\n", bit_idx);
                    return -1;
                }
            }
            timeout = 0;
            while (gpiod_line_get_value(line) == 1) {
                usleep(1);
                timeout++;
                if (timeout > 100) {
                    fprintf(stderr, "DHT22 timeout on bit %d (high)\n", bit_idx);
                    return -1;
                }
            }
            data[byte_idx] <<= 1;
            if (timeout > 50) {
                data[byte_idx] |= 1;
            }
            if (bit_idx % 8 == 7) {
                byte_idx++;
            }
        }

        /* --- Checksum --- */
        int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
        if (checksum != data[4]) {
            fprintf(stderr, "DHT22 checksum error (calc=%d, recv=%d)\n",
                    checksum, data[4]);
            return -1;
        }

        /* --- Convert --- */
        *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
        *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
        if (data[2] & 0x80) {
            *temperature = -*temperature;
        }

        return 0;
    }

    fprintf(stderr, "DHT22 read failed after %d attempts\n", DHT22_MAX_RETRIES);
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", DHT22_PIN_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", DHT22_PIN_2, strerror(errno));
        goto cleanup;
    }

    /* --- Request both lines as inputs --- */
    if (gpiod_line_request_input(line1, "dht22") < 0) {
        fprintf(stderr, "Failed to request input for pin %d: %s\n",
                DHT22_PIN_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "dht22") < 0) {
        fprintf(stderr, "Failed to request input for pin %d: %s\n",
                DHT22_PIN_2, strerror(errno));
        goto cleanup;
    }

    printf("DHT22 monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    for (int cycle = 0; cycle < DHT22_CYCLES && program_running; cycle++) {
        float temperature = 0.0f;
        float humidity = 0.0f;

        if (read_dht22(line1, &temperature, &humidity) == 0) {
            printf("Cycle %d: Humidity = %.1f%%, Temperature = %.1fC\n",
                   cycle + 1, humidity, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Cycle %d: Failed to read DHT22\n", cycle + 1);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < DHT22_READ_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

