            }
            sleep_us(1);
            if (now_us() - end > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo low.\n");
                break;
            }
        }

        long long pulse_us = end - start;
        long long distance = (pulse_us > 0) ? (pulse_us * 34300L / 2L) / 1000L : 0;

        printf("Distance: %lld mm\n", distance);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

