#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define BMP280_I2C_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_26 0xE1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(int fd, int32_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                                   int32_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                                   int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                                   int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t calib[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, calib, 24) < 0) return -1;

    *dig_T1 = (calib[1] << 8) | calib[0];
    *dig_T2 = (calib[3] << 8) | calib[2];
    *dig_T3 = (calib[5] << 8) | calib[4];
    *dig_P1 = (calib[7] << 8) | calib[6];
    *dig_P2 = (calib[9] << 8) | calib[8];
    *dig_P3 = (calib[11] << 8) | calib[10];
    *dig_P4 = (calib[13] << 8) | calib[12];
    *dig_P5 = (calib[15] << 8) | calib[14];
    *dig_P6 = (calib[17] << 8) | calib[16];
    *dig_P7 = (calib[19] << 8) | calib[18];
    *dig_P8 = (calib[21] << 8) | calib[20];
    *dig_P9 = (calib[23] << 8) | calib[22];
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) return -1;
    if (id != 0x58) {
        fprintf(stderr, "BMP280 not detected (ID=0x%02X, expected 0x58)\n", id);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) return -1;
    usleep(2000);
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read(int fd, int32_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                       int32_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                       int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                       int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9,
                       int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    int32_t raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    int32_t var1, var2, t_fine;
    var1 = ((((raw_t >> 3) - ((int32_t)*dig_T1 << 1))) * ((int32_t)*dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)*dig_T1)) * ((raw_t >> 4) - ((int32_t)*dig_T1))) >> 12) * ((int32_t)*dig_T3)) >> 14;
    t_fine = var1 + var2;
    *temperature = (t_fine * 5 + 128) >> 8;

    int64_t v1, v2, p;
    v1 = ((int64_t)t_fine) - 128000;
    v2 = v1 * v1 * (int64_t)*dig_P1;
    v2 = v2 + ((v1 * (int64_t)*dig_P2) << 17);
    v2 = v2 + (((int64_t)*dig_P3) << 35);
    v1 = ((v1 * v1 * (int64_t)*dig_P4) >> 15) + ((v1 * (int64_t)*dig_P5) << 12);
    v1 = (((((int64_t)*dig_P6) << 31) + v1) * v1) >> 15;
    v1 = v1 + (((int64_t)*dig_P7) << 25);
    v1 = v1 >> 33;
    v2 = (((int64_t)*dig_P8) << 19) + v2;
    v2 = v2 + (((int64_t)*dig_P9) << 12);
    p = 1048576 - raw_p;
    p = (((p << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)*dig_P10) << 13) + p;
    v2 = p * p * (int64_t)*dig_P11;
    p = (int32_t)((p + v2) >> 8);
    *pressure = p;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(fd);
        return 1;
    }

    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    if (bmp280_read_calibration(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3,
                                &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    int rc = 0;
    for (int i = 0; i < 3 && running; i++) {
        int32_t temp, press;
        if (bmp280_read(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3,
                        &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9, &temp, &press) < 0) {
            fprintf(stderr, "Read failed, exiting\n");
            rc = 1;
            break;
        }
        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp / 100.0, press / 100.0);
        fflush(stdout);
        usleep(1000000);
    }

    close(fd);
    return rc;
}

