#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

#define BME280_CHIP_ID 0x60

static int i2c_fd = -1;

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_init(void) {
    uint8_t id;
    if (i2c_read_reg(BME280_REG_ID, &id) < 0) {
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 not found (ID=0x%02X, expected 0x%02X)\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(BME280_REG_RESET, 0xB6) < 0) return -1;
    usleep(2000);

    if (i2c_write_reg(BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_burst(BME280_REG_DATA, data, 8) < 0) return -1;

    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];

    *press = (float)raw_press / 100.0f;
    *temp = (float)raw_temp / 100.0f;
    *hum = (float)raw_hum / 1024.0f;

    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bme280_init() < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    float temp, hum, press;
    for (int i = 0; i < 3; i++) {
        if (bme280_read(&temp, &hum, &press) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%, Pressure: %.2f hPa\n", temp, hum, press);
        } else {
            fprintf(stderr, "Failed to read BME280 data\n");
        }
        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

