#include <termios.h>
#include <errno.h>
#include <signal.h>

#define BAUD_RATE B9600
#define READ_BUF_SIZE 256
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void print_data(const char *data) {
    printf("Received: %s\n", data);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = init_uart("/dev/ttyS0");
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    char read_buf[READ_BUF_SIZE];
    ssize_t bytes_read;

    while (g_running) {
        bytes_read = read(fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read > 0) {
            read_buf[bytes_read] = '\0';
            print_data(read_buf);
        } else if (bytes_read == 0) {
            fprintf(stderr, "Device disconnected or not responding.\n");
            break;
        } else {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hcsr04"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig, 1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1;
    }
    return 0;
}

static long measure_distance(struct gpiod_line *echo) {
    struct timespec t0, t1;
    long elapsed_us;

    if (trigger_sensor(echo) < 0)
        return -1;

    /* Wait for echo rising edge */
    while (gpiod_line_get_value(echo) == 0) {
        if (!keep_running)
            return -1;
        usleep(100);
    }
    clock_gettime(CLOCK_MONOTONIC, &t0);

    /* Wait for echo falling edge */
    while (gpiod_line_get_value(echo) == 1) {
        if (!keep_running)
            return -1;
        usleep(100);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);

    elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                 (t1.tv_nsec - t0.tv_nsec) / 1000L;

    /* Speed of sound: 343 m/s => 343000 cm/s => 0.0343 cm/us */
    return (long)((elapsed_us / 2) * 0.0343);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trig)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (keep_running) {
        long dist = measure_distance(echo);

        if (dist < 0) {
            fprintf(stderr, "Error: sensor read failed\n");
        } else if (dist < 0 || dist > 400) {
            fprintf(stderr, "Warning: out-of-range reading %ld cm\n", dist);
        } else {
            printf("Distance: %ld cm\n", dist);
            fflush(stdout);
        }

        usleep(500000);
    }

    printf("\nExiting...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return rc;
}

