#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FILTER_CTL 0x2F
#define ADXL345_REG_DEVID 0x00

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg(fd, ADXL345_REG_DEVID, &devid) < 0) return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }

    if (i2c_write_reg(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_reg(fd, ADXL345_REG_FILTER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (adxl345_init(fd) < 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        close(fd);
        return 1;
    }

    printf("ADXL345 ready. Reading data...\n");

    while (running) {
        uint8_t x = 0, y = 0, z = 0;
        if (i2c_read_reg(fd, ADXL345_REG_DATAX0, &x) < 0 ||
            i2c_read_reg(fd, ADXL345_REG_DATAY0, &y) < 0 ||
            i2c_read_reg(fd, ADXL345_REG_DATAZ0, &z) < 0) {
            fprintf(stderr, "Read error, exiting.\n");
            break;
        }
        printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        usleep(100000);
    }

    close(fd);
    return 0;
}

