void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM pin 23 */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line 23");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line 23 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 23 set to LOW (0)\n");
    fflush(stdout);

    /* Sleep for 1 second (1,000,000 microseconds) */
    usleep(1000000);

    /* Set the line high */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line 23 high");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 23 set to HIGH (1)\n");
    fflush(stdout);

    /* Sleep for 1 second */
    usleep(1000000);

    /* Release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO 23 released.\n");
    return EXIT_SUCCESS;
}

