#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 30000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int target, long long timeout_us) {
    long long start = now_us();
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        if (now_us() - start > timeout_us) return -1;
    }
    return -1;
}

static long long measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    long long start = now_us();
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);

    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) return -1;
    long long pulse_start = now_us();

    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) return -1;
    long long pulse_end = now_us();

    if (pulse_end - pulse_start > TIMEOUT_US) return -1;

    long long pulse_duration = pulse_end - pulse_start;
    return (pulse_duration * 34300LL) / 2LL;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIG_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output trig");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input echo");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        long long distance = measure_distance(trig, echo);
        if (distance < 0 || distance > 2000) {
            printf("Error: Invalid distance measurement.\n");
        } else {
            printf("Distance: %lld mm\n", distance);
        }
        fflush(stdout);
        usleep(500000);
    }

    gpiod_line_set_value(trig, 0);
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

