#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ECHO_TIMEOUT_US 300000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us) {
    if (us <= 0) return;
    struct timespec ts = {
        .tv_sec = us / 1000000LL,
        .tv_nsec = (us % 1000000LL) * 1000LL
    };
    nanosleep(&ts, NULL);
}

static long long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo) {
    long long t0 = now_us();
    if (t0 < 0) return -1;

    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    sleep_us(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    long long timeout = t0 + ECHO_TIMEOUT_US;
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() >= timeout) return -1;
    }
    long long start = now_us();

    timeout = start + ECHO_TIMEOUT_US;
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() >= timeout) return -1;
    }
    long long end = now_us();

    return end - start;
}

static void report(long long distance_mm) {
    if (distance_mm < 2 || distance_mm > 400) {
        printf("Error: distance out of range (%lld mm)\n", distance_mm);
    } else {
        printf("Distance: %lld mm\n", distance_mm);
    }
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        long long pulse = measure_pulse(trig, echo);
        if (pulse < 0) {
            fprintf(stderr, "Error: timeout waiting for echo\n");
        } else {
            report(pulse);
        }
        sleep_us(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

