        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (keep_running) {
        /* Ensure trigger is low for at least 2 us */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            goto cleanup;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value trig high");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            goto cleanup;
        }

        /* Wait for echo rising edge */
        int waited = 0;
        while (gpiod_line_get_value(echo) == 0) {
            if (!keep_running) break;
            if (waited > 100000) {
                fprintf(stderr, "Timeout waiting for echo rising edge\n");
                goto cleanup;
            }
            usleep(1);
            waited++;
        }
        if (!keep_running) break;
        if (waited > 100000) {
            goto cleanup;
        }

        /* Measure echo high duration */
        int echo_val = 0;
        waited = 0;
        while (gpiod_line_get_value(echo) == 1) {
            if (!keep_running) break;
            if (waited > 100000) {
                fprintf(stderr, "Timeout waiting for echo falling edge\n");
                goto cleanup;
            }
            usleep(1);
            waited++;
        }
        if (!keep_running) break;
        if (waited > 100000) {
            goto cleanup;
        }
        echo_val = waited;

        /* Calculate distance in cm: speed of sound ~343 m/s, round trip */
        float distance = (echo_val * 34300.0f) / 2000000.0f;

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (gnd) gpiod_line_release(gnd);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

